import{_ as r,o as s,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"From Classical to the Future - Matan Breizman, IBM","description":"","frontmatter":{"title":"From Classical to the Future - Matan Breizman, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Crimson项目","异步编程","C","star框架","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/From_Classical_to_the_Future_-_Matan_Breizman_IBM.md","filePath":"posts/2023/From_Classical_to_the_Future_-_Matan_Breizman_IBM.md","lastUpdated":1780459816000}'),e={name:"posts/2023/From_Classical_to_the_Future_-_Matan_Breizman_IBM.md"};function n(i,t,_,p,l,C){return s(),a("div",null,[...t[0]||(t[0]=[o("<p>Matan Breizman在IBM举办的会议上介绍了Crimson项目的进展，这是Ceph分布式存储系统的一个关键项目。以下是对会议内容的总结：</p><ol><li><p><strong>背景介绍</strong>：Matan Breizman介绍了他在Crimson项目上的工作，该项目旨在提高Ceph存储设备的速度和效率。</p></li><li><p><strong>技术挑战</strong>：讨论了CPU和存储设备发展速度不匹配的问题，以及单核性能增长停滞，而逻辑核心数量增加的趋势。</p></li><li><p><strong>Crimson项目目标</strong>：目标是减少CPU开销，通过避免上下文切换和跨核心通信来充分利用快速存储设备。Crimson是对当前OSD I/O路径的重新编写，使用C-star框架以提高效率。</p></li><li><p><strong>C-star框架介绍</strong>：C-star是一个开源的C++异步编程框架，适用于现代硬件，强调共享无设计、未来与承诺以及消息传递等关键概念。</p></li><li><p><strong>代码重构示例</strong>：展示了如何将传统的同步代码转换为使用C-star框架的异步代码，强调了在Crimson中处理I/O请求时，如何通过未来与承诺来避免昂贵的上下文切换。</p></li><li><p><strong>性能优化</strong>：讨论了在Crimson中如何通过避免上下文切换来减少CPU开销，从而提高性能。</p></li><li><p><strong>未来工作与参与方式</strong>：鼓励社区成员参与Crimson项目，提供了加入会议和参与开发的建议。</p></li><li><p><strong>后续行动计划</strong>：继续推进Crimson项目的开发，特别是性能优化方面；鼓励社区成员参与项目，提供更多的文档和开发指导。</p></li></ol><p>会议中讨论的关键点包括Crimson项目如何通过C-star框架和异步编程来减少CPU开销，以及如何通过优化代码来提高性能。此外，会议还强调了社区参与和性能测试的重要性。</p><p>[改进后的总结保留了以下关键词，以确保准确反映Ceph相关领域的英文原文关键词]：Ceph, Crimson项目, 异步编程, C-star框架, CPU开销, I/O路径, 性能优化, 分布式存储, 异步编程, 共享无设计, 未来与承诺, 消息传递, 代码重构, 性能测试, 社区参与。</p>",4)])])}const g=r(e,[["render",n]]);export{c as __pageData,g as default};
